/**
 * Slice 5a falsifiers (ADR 0035 rule 4; docs/features/routes/REGISTRY-SHAPE.md). Red until the fill
 * lands: one generated registry, no per-route generated file, the host read in the route directory,
 * the capability inferred from it, and the icon any Lucide name. Each test prints what it found.
 */
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { expect, test } from "vite-plus/test";

const ts = resolve(import.meta.dirname, "../../..");
const at = (path: string) => join(ts, path);
const firstLine = (path: string) => readFileSync(path, "utf8").split(/\r?\n/, 1)[0] ?? "";
const dirs = (path: string) =>
  readdirSync(at(path), { withFileTypes: true }).filter((entry) => entry.isDirectory()).map((entry) => entry.name);

const ONE_REGISTRY = "apps/host/src/routes.generated.ts";
const OLD_REGISTRIES = [
  "apps/web/src/route/builtin-modules.generated.ts",
  "apps/web/src/route/builtin-closures.generated.ts",
  "apps/web/src/route/builtin-typed.generated.ts",
  "apps/web/src/route/links.generated.ts",
  "apps/host/src/reads/builtins.generated.ts",
  "apps/host/src/reads/registry.generated.ts",
];

test("one generated registry: apps/host/src/routes.generated.ts and none of the six", () => {
  expect({
    absent: [ONE_REGISTRY].filter((path) => !existsSync(at(path))),
    stillPresent: OLD_REGISTRIES.filter((path) => existsSync(at(path))),
  }).toEqual({ absent: [], stillPresent: [] });
});

test("admitted-builtin-keys is derived from the registry, not generated", () => {
  expect(["packages/agent-contracts/src/admitted-builtin-keys.ts"].filter((path) => existsSync(at(path)))).toEqual([]);
});

test("no per-route TanStack file: routes/ holds hand-written files only", () => {
  const generated = readdirSync(at("apps/web/src/routes"))
    .filter((name) => name.endsWith(".tsx") && firstLine(at(`apps/web/src/routes/${name}`)).startsWith("// Generated by codegen:routes"))
    .map((name) => `apps/web/src/routes/${name}`);
  expect(generated).toEqual([]);
});

test("no per-route contract stub: the address table is one generated file", () => {
  const generated = readdirSync(at("packages/agent-contracts/src/routes"))
    .filter((name) => name.endsWith(".ts") && firstLine(at(`packages/agent-contracts/src/routes/${name}`)).startsWith("// Generated from"))
    .map((name) => `packages/agent-contracts/src/routes/${name}`);
  expect(generated).toEqual([]);
});

test("no generated file in a route directory: types are inferred", () => {
  const generated = dirs("apps/web/src").flatMap((folder) =>
    ["context", "host", "neutral"].map((name) => `apps/web/src/${folder}/${name}.generated.ts`).filter((path) => existsSync(at(path))),
  );
  expect(generated).toEqual([]);
});

test("the generator no longer forces a host read out of its route directory", () => {
  const source = readFileSync(at("apps/web/scripts/route-graphs.ts"), "utf8");
  expect(source.includes("must live under apps/host"), "route-graphs.ts still refuses a host read outside apps/host").toBe(false);
});

test("a builtin's host read lives in its directory as host.ts, and apps/host/src/reads/<key>.ts is gone", () => {
  const offenders: string[] = [];
  for (const folder of dirs("apps/web/src")) {
    const declaration = at(`apps/web/src/${folder}/route.ts`);
    if (!existsSync(declaration)) continue;
    const source = readFileSync(declaration, "utf8");
    const key = source.match(/^\s*key:\s*"([^"]+)"/m)?.[1];
    const host = source.match(/^\s*host:\s*"([^"]+)"/m)?.[1];
    if (host && host !== "./host.ts") offenders.push(`apps/web/src/${folder}/route.ts names host ${host}`);
    if (key && existsSync(at(`apps/host/src/reads/${key}.ts`))) offenders.push(`apps/host/src/reads/${key}.ts still exists`);
  }
  expect(offenders).toEqual([]);
});

test("the capability type is inferred from the host read: contracts hold no hand capability object", () => {
  const offenders = readdirSync(at("packages/agent-contracts/src"))
    .filter((name) => name.endsWith(".ts"))
    .flatMap((name) => {
      const found = readFileSync(at(`packages/agent-contracts/src/${name}`), "utf8").match(/export const \w+Capability\s*=/g) ?? [];
      return found.map((line) => `packages/agent-contracts/src/${name}: ${line}`);
    });
  expect(offenders).toEqual([]);
});

test("the icon is any Lucide name: no closed union in contracts, no hand icon map in the catalogue", () => {
  const directory = readFileSync(at("packages/agent-contracts/src/route-directory.ts"), "utf8");
  const catalogue = readFileSync(at("apps/web/src/navigation/catalogue.ts"), "utf8");
  const offenders = [
    ...(/iconKey:\s*(?:\r?\n\s*)?\|\s*"/.test(directory) ? ["packages/agent-contracts/src/route-directory.ts: iconKey is a closed string union"] : []),
    ...(/const ICONS\s*=/.test(catalogue) ? ["apps/web/src/navigation/catalogue.ts: a hand ICONS map instead of lucide-react's icons"] : []),
  ];
  expect(offenders).toEqual([]);
});
